// ─── UPDATE THESE THREE VALUES ──────────────────────────────────
const sheetId            = 'PASTE_YOUR_GOOGLE_SHEET_ID_HERE';
const channelWebhookUrl  = 'PASTE_YOUR_N8N_CHANNEL_WEBHOOK_URL_HERE';
const apiKey             = 'PASTE_YOUR_YOUTUBE_DATA_API_KEY_HERE';
// ─────────────────────────────────────────────────────────────────

if (sheetId === 'PASTE_YOUR_GOOGLE_SHEET_ID_HERE') {
  throw new Error('Auto-scan is not configured yet. Open the "Configuration" node and fill in your sheetId, channelWebhookUrl, and apiKey.');
}

return [{ json: { sheetId, channelWebhookUrl, apiKey } }];

// Filter to active channels only, build payload for each
const config = $('Configuration').first().json;
const rows = $input.all();

const activeChannels = rows.filter(row => {
  const active = String(row.json['Active'] || '').toUpperCase();
  return active === 'TRUE' || active === 'YES' || active === '1';
});

if (activeChannels.length === 0) {
  throw new Error('No active channels found in the Channels sheet. Set column C to TRUE for at least one row.');
}

return activeChannels.map(row => ({
  json: {
    channelUrl: row.json['Channel URL'],
    keywords: (row.json['Keywords'] || '').split(',').map(k => k.trim()).filter(Boolean),
    apiKey: config.apiKey,
    sheetId: config.sheetId,
    channelWebhookUrl: config.channelWebhookUrl
  }
}));

